CREATE TABLE cliente (cpf VARCHAR(11) PRIMARY KEY, nome VARCHAR(150) NOT NULL, email VARCHAR(150) NOT NULL UNIQUE, senha VARCHAR(255) NOT NULL, data_nascimento DATE NOT NULL, status_conta BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE gerente (id_gerente INT AUTO_INCREMENT PRIMARY KEY, nome VARCHAR(150) NOT NULL, email VARCHAR(150) NOT NULL UNIQUE, senha VARCHAR(255) NOT NULL);
CREATE TABLE dependente (id_dependente INT AUTO_INCREMENT PRIMARY KEY, nome VARCHAR(150) NOT NULL, data_nascimento DATE NOT NULL, cliente_cpf VARCHAR(11) NOT NULL, FOREIGN KEY (cliente_cpf) REFERENCES cliente(cpf));
CREATE TABLE jogo (codigo_jogo INT AUTO_INCREMENT PRIMARY KEY, nome VARCHAR(150) NOT NULL, categoria VARCHAR(100), genero VARCHAR(100), faixa_etaria_recomendada INT, preco_locacao DECIMAL(10,2) NOT NULL, quantidade_estoque INT NOT NULL DEFAULT 0, status_disponibilidade BOOLEAN NOT NULL DEFAULT TRUE, gerente_id INT, FOREIGN KEY (gerente_id) REFERENCES gerente(id_gerente));
CREATE TABLE aluguel_reserva (id_aluguel INT AUTO_INCREMENT PRIMARY KEY, data_hora_reserva DATETIME NOT NULL, data_limite_retirada DATETIME NOT NULL, data_devolucao_real DATETIME, status VARCHAR(20) NOT NULL, valor_total DOUBLE NOT NULL, quantidade_renovacoes INT NOT NULL DEFAULT 0, cliente_cpf VARCHAR(11) NOT NULL, dependente_id INT, termos_danos TEXT, termos_contrato TEXT, precificacao_multa DOUBLE, data_assinatura DATETIME, FOREIGN KEY (cliente_cpf) REFERENCES cliente(cpf), FOREIGN KEY (dependente_id) REFERENCES dependente(id_dependente));
CREATE TABLE contem (jogo_codigo INT NOT NULL, aluguel_id INT NOT NULL, PRIMARY KEY (jogo_codigo, aluguel_id), FOREIGN KEY (jogo_codigo) REFERENCES jogo(codigo_jogo), FOREIGN KEY (aluguel_id) REFERENCES aluguel_reserva(id_aluguel));
CREATE TABLE penalidade (id_penalidade INT AUTO_INCREMENT PRIMARY KEY, tipo_penalidade VARCHAR(50) NOT NULL, valor_multa DOUBLE NOT NULL, data_fim_suspensao DATE, aluguel_id INT NOT NULL, FOREIGN KEY (aluguel_id) REFERENCES aluguel_reserva(id_aluguel));
CREATE INDEX idx_jogo_genero ON jogo(genero);
CREATE INDEX idx_jogo_faixa_etaria ON jogo(faixa_etaria_recomendada);
CREATE INDEX idx_aluguel_status ON aluguel_reserva(status);
CREATE INDEX idx_aluguel_cliente ON aluguel_reserva(cliente_cpf);
